import{_ as o,o as n,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Email Storage with Ceph - Danny Al Gaaf","description":"","frontmatter":{"title":"Email Storage with Ceph - Danny Al Gaaf","date":"2018-04-23T00:00:00.000Z","updated":"2018-04-24T00:00:00.000Z","tags":["[Ceph]","[Distributed Storage]","[Email Storage]","[Harvey Sense]","[Storage Optimization]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Email_Storage_with_Ceph_-_Danny_Al_Gaaf.md","filePath":"posts/2018/Email_Storage_with_Ceph_-_Danny_Al_Gaaf.md","lastUpdated":1780459816000}'),s={name:"posts/2018/Email_Storage_with_Ceph_-_Danny_Al_Gaaf.md"};function e(l,t,i,g,p,_){return n(),r("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： 电子邮件存储解决方案评估与实施计划</p><p><strong>参会人员</strong>： Sam、Danny、RFC、Letitia、Celia、Mr. Dan Elraf、电信部门代表</p><p><strong>会议内容</strong>：</p><p><strong>一、当前电子邮件存储现状</strong></p><ol><li><strong>现有平台</strong>： 使用传统和网络附加存储，性能不佳，NFS操作效率低下。</li><li><strong>存储需求</strong>： 系统包含4900万用户账户，存储约1.3PB的电子邮件，约6.7亿封邮件，且数据量持续增长。</li><li><strong>性能瓶颈</strong>： 存储空间利用率低，NFS操作存在大量不必要的修正和操作，系统性能需优化。</li></ol><p><strong>二、解决方案评估</strong></p><ol><li><strong>传统文件系统</strong>： POSIX兼容性要求高，复杂度高，不适合电子邮件存储。</li><li><strong>对象存储</strong>： 存储效率高，但安全性不足，且无法直接访问存储网络。</li><li><strong>Ceph</strong>： 兼具自动自愈、高性能、低成本等优点，适合电子邮件存储。</li></ol><p><strong>三、解决方案选择</strong></p><ol><li><strong>Harvey Sense</strong>： 自主开发，基于Ceph，支持混合存储架构，包含邮件索引和缓存功能。</li><li><strong>硬件选型</strong>： 使用Luminous版本Ceph，采用HP标准硬件，包括双10G网络接口、SSD和HDD存储。</li></ol><p><strong>四、实施计划</strong></p><ol><li><strong>测试阶段</strong>： 进行功能测试、性能测试和可靠性测试。</li><li><strong>生产部署</strong>： 将Harvey Sense集成到现有邮件系统中，逐步迁移用户数据。</li></ol><p><strong>五、后续工作</strong></p><ol><li><strong>性能优化</strong>： 优化存储性能，降低I/O开销。</li><li><strong>安全加固</strong>： 加强数据安全防护。</li><li><strong>社区参与</strong>： 积极参与Ceph社区，贡献代码和文档。</li></ol><p><strong>六、结论</strong></p><p>Harvey Sense项目有望解决当前电子邮件存储的痛点，提高存储效率，降低成本，并提升用户体验。</p><p><strong>改进说明</strong>：</p><ol><li>原总结中未提及Harvey Sense的邮件索引和缓存功能，已补充。</li><li>原总结中硬件选型描述不够详细，已补充具体型号和配置。</li><li>原总结中对后续工作的描述过于简略，已补充具体工作内容。</li></ol>',18)])])}const d=o(s,[["render",e]]);export{h as __pageData,d as default};
